 ('Nursys QuickConfirm', 'MANUAL_DOCUMENT_REVIEW', false, 'Free license and discipline lookup with data sent by participating boards (every US jurisdiction except Puerto Rico). Nursys meets The Joint Commission’s principles for primary-source-equivalent verification.', 'https://www.nursys.com/LQC/LQCTerms.aspx', 'nursys-quickconfirm', 'NURSYS', null, array['US-AL','US-AK','US-AZ','US-AR','US-CA','US-CO','US-CT','US-DE','US-DC','US-FL','US-GA','US-HI','US-ID','US-IL','US-IN','US-IA','US-KS','US-KY','US-LA','US-ME','US-MD','US-MA','US-MI','US-MN','US-MS','US-MO','US-MT','US-NE','US-NV','US-NH','US-NJ','US-NM','US-NY','US-NC','US-ND','US-OH','US-OK','US-OR','US-PA','US-RI','US-SC','US-SD','US-TN','US-TX','US-UT','US-VT','US-VA','US-WA','US-WV','US-WI','US-WY','US-AS','US-GU','US-MP','US-VI']::text[], array['RN_LICENSE','RN_LICENSE_MULTISTATE']::text[], 'PRIMARY_SOURCE_EQUIVALENT', 'PRIMARY_SOURCE_VERIFIED', false, 'Nursys does not offer an API for QuickConfirm. Manual lookup only (free).', 'APPROVED', false, null, '2026-10-09'),
 ('Nursys e-Notify (institution API)', 'PRIMARY_SOURCE_API', false, 'Not connected: Veridun has no institution account or API credentials yet. The connector is a server-side stub (backend/supabase/functions/nursys-enotify) that refuses to run without them. Once connected, enrolled licenses become Continuously Monitored.', 'https://www.nursys.com/Help/FAQ.aspx?KEY=EN', 'nursys-enotify', 'NURSYS', null, array['US-AL','US-AK','US-AZ','US-AR','US-CA','US-CO','US-CT','US-DE','US-DC','US-FL','US-GA','US-HI','US-ID','US-IL','US-IN','US-IA','US-KS','US-KY','US-LA','US-ME','US-MD','US-MA','US-MI','US-MN','US-MS','US-MO','US-MT','US-NE','US-NV','US-NH','US-NJ','US-NM','US-NY','US-NC','US-ND','US-OH','US-OK','US-OR','US-PA','US-RI','US-SC','US-SD','US-TN','US-TX','US-UT','US-VT','US-VA','US-WA','US-WV','US-WI','US-WY','US-AS','US-GU','US-MP','US-VI']::text[], array['RN_LICENSE','RN_LICENSE_MULTISTATE']::text[], 'PRIMARY_SOURCE_EQUIVALENT', 'PRIMARY_SOURCE_VERIFIED', true, 'Free Nursys e-Notify institution account; API credentials requested from NCSBN for that account; API password must be changed every 90 days; no test environment or sample nurses; licenses must be enrolled on the account’s Nurse List before data comes back. JSON API: manage the Nurse List, pull Nurse Report license data, pull license-change notifications.', 'PENDING', true, null, '2026-10-09'),
