update public.requirement_sets set policy_code = 'VDN-' || key || '-BASE', policy_version = '2026.1', effective_on = '2026-10-01', required_by = authority where owner_org_id is null and layer = 'WORK_TYPE';
update public.requirement_sets set policy_code = 'VDN-SPEC-' || key, policy_version = '2026.2', effective_on = '2026-10-08', required_by = authority where owner_org_id is null and layer = 'SPECIALTY';
update public.requirement_sets set policy_code = 'STATE-' || replace(key, 'US-', '') || '-RN-AUTH', policy_version = '2026-10-08', required_by = authority where owner_org_id is null and layer = 'STATE';
update public.requirements r set min_verification_level = case when r.is_rn_authorization then 'PRIMARY_SOURCE_VERIFIED' else c.min_verification_level end,
  validity_rule = case when r.is_rn_authorization then 'Must authorize RN practice in the assignment state and stay active through the assignment end'
    when r.recency_months is not null then 'At least ' || coalesce(r.min_months, r.recency_months) || ' months of this specialty in the ' || r.recency_months || ' months before the start date'
    else 'Must stay valid through the assignment end' end
from public.requirement_sets s, public.credential_catalog c
where s.id = r.requirement_set_id and s.owner_org_id is null and (c.kind = r.kind or (r.is_rn_authorization and c.kind = 'RN_LICENSE'));

commit;
